SELECT COUNT(DISTINCT id) AS paidOrderCount, COALESCE(SUM(payment_price), 0) AS amount
FROM order_info WHERE del_flag = '0' AND is_pay = '1' AND payment_time IS NOT NULL
  AND payment_time >= #{window.startAt} AND payment_time < #{window.endAt}

SELECT CAST(create_time AS date) AS date, COUNT(*) AS paidOrderCount, 0 AS amount FROM user_info
WHERE del_flag = '0' AND create_time >= #{window.startAt} AND create_time < #{window.endAt}
GROUP BY CAST(create_time AS date) ORDER BY date
